f = lambda x: 'f%s' % x
def tx(*xs): return [(f(k), s) for k, s in xs]
def li(*xs): return [{'icono': i, 'txt': s, 't': f(k)} for i, s, k in xs]
def R(p, *t, p2=None, t2=None, et=None):
    e = {'tipo': 'retrato', 'personaje': p, 'texto': tx(*t)}
    if p2: e['personaje2'] = p2; e['t2'] = f(t2)
    if et: e['etiqueta'] = et
    return e
def V(cita, txt, k_fin): return {'tipo': 'versiculo', 'cita': cita + RV, 'version': False, 'versiculo': txt, 'tInicio': 0.4, 'tEscritura': f(k_fin)}
def ESC(preset, *t, sem=1): return {'tipo': 'escenario', 'preset': preset, 'semilla': sem, 'texto': tx(*t)}
